// ===========================================================
// TRAITEMENT DES TENDANCES REDDIT
// ===========================================================
const items = $input.all();
const redditData = items[0]?.json;

const posts = redditData?.data?.children || [];
const trends = [];

for (const post of posts) {
  const d = post.data;
  if (d.score >= 500 && !d.over_18 && d.title) {
    const words = d.title
      .toLowerCase()
      .replace(/[^a-z0-9 ]/g, ' ')
      .split(' ')
      .filter(w => w.length > 4)
      .slice(0, 8);

    trends.push({
      source: 'Reddit',
      title: d.title,
      score: d.score,
      comments: d.num_comments,
      subreddit: 'r/' + d.subreddit,
      url: 'https://reddit.com' + d.permalink,
      trend_score: Math.round(d.score * 0.7 + d.num_comments * 30),
      keywords: words,
      category: d.subreddit,
      content_type: d.is_video ? 'video' : (d.is_self ? 'text' : 'link')
    });
  }
}

const top12 = trends
  .sort((a, b) => b.trend_score - a.trend_score)
  .slice(0, 12);

console.log(`Reddit: ${posts.length} posts analysés → ${top12.length} retenus`);

return top12.map(t => ({ json: t }));

// ===========================================================
// TRAITEMENT DES TENDANCES GOOGLE DAILY TRENDS
// ===========================================================
const items = $input.all();
const rawResponse = items[0]?.json;

let googleTrends = [];

try {
  let jsonStr = typeof rawResponse === 'string'
    ? rawResponse
    : JSON.stringify(rawResponse);

  const cleanStr = jsonStr.replace(/^\)\]}'[,\s]*/, '').trim();

  let data;
  try {
    data = JSON.parse(cleanStr);
  } catch (e) {
    data = rawResponse;
  }

  const trendDays = data?.default?.trendingSearchesDays || [];
  const searches = trendDays.length > 0 ? (trendDays[0].trendingSearches || []) : [];

  for (const trend of searches) {
    const query = trend.title?.query || '';
    if (!query) continue;

    const rawTraffic = trend.formattedTraffic || '1K+';
    const traffic = parseInt(rawTraffic.replace(/[^0-9]/g, '')) || 1000;
    const multiplier = rawTraffic.includes('M') ? 1000 : 1;

    googleTrends.push({
      source: 'Google Trends',
      title: query,
      score: traffic * multiplier,
      comments: 0,
      subreddit: '',
      url: `https://trends.google.com/trends/explore?q=${encodeURIComponent(query)}&geo=US`,
      trend_score: (traffic * multiplier) * 8,
      keywords: query.toLowerCase().split(' ').filter(w => w.length > 2),
      category: trend.articles?.[0]?.source?.name || 'News',
      traffic_label: rawTraffic,
      articles: (trend.articles || []).slice(0, 3).map(a => a.title).filter(Boolean)
    });
  }

} catch (e) {
  console.error('Erreur parsing Google Trends:', e.message);
  googleTrends = [{
    source: 'Google Trends',
    title: 'AI Technology Products 2025',
    score: 500000,
    trend_score: 4000000,
    keywords: ['ai', 'technology', 'products', '2025'],
    category: 'Technology',
    traffic_label: '500K+',
    url: 'https://trends.google.com/trends/?geo=US'
  }];
}

console.log(`Google Trends: ${googleTrends.length} tendances récupérées`);

return googleTrends.slice(0, 12).map(t => ({ json: t }));

// ===========================================================
// FUSION, DÉDUPLICATION ET SÉLECTION TOP 5
// ===========================================================
const allTrends = $input.all().map(item => item.json);

const excludedCategories = ['politics', 'worldnews', 'news', 'askreddit'];

const affiliateBonus = {
  'technology': 2.0, 'gaming': 1.8, 'gadgets': 2.2, 'deals': 2.5,
  'frugal': 2.3, 'buyitforlife': 2.4, 'fitness': 1.9, 'personalfinance': 1.8,
  'travel': 1.7, 'food': 1.5, 'home': 1.8, 'beauty': 1.7,
  'fashion': 1.6, 'Science': 1.5, 'Technology': 2.0
};

const seen = new Set();
const deduplicated = [];

for (const trend of allTrends) {
  const title = trend.title || '';
  if (!title || title.length < 5) continue;

  const cat = (trend.category || '').toLowerCase();
  if (excludedCategories.some(exc => cat.includes(exc))) continue;

  const key = title.toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 25);

  if (!seen.has(key)) {
    seen.add(key);
    const bonus = affiliateBonus[trend.category] || 1.0;
    const finalScore = Math.round(trend.trend_score * bonus);
    deduplicated.push({
      ...trend,
      trend_score: finalScore,
      affiliate_potential: bonus >= 2.0 ? 'high' : bonus >= 1.6 ? 'medium' : 'standard'
    });
  }
}

const top5 = deduplicated
  .sort((a, b) => b.trend_score - a.trend_score)
  .slice(0, 5)
  .map((t, index) => ({
    ...t,
    rank: index + 1,
    processed_at: new Date().toISOString(),
    execution_date: new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
  }));

console.log(`Total fusionné: ${allTrends.length} → Sélectionnés: ${top5.length}`);

return top5.map(t => ({ json: t }));

