try {
  const cleaned = rawText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
  content = JSON.parse(cleaned);
} catch (parseError) {
  console.error('Fallback mode - JSON parse failed:', parseError.message);
  const title = item.title || 'Trending Topic';
  content = {
    topic_analysis: { main_theme: title, affiliate_angle: 'Product recommendations', monetization_potential: 'medium' },
    twitter_thread: {
      tweet_1: `🔥 ${title} is taking the US by storm! Here's everything you need to know 👇`,
      tweet_2: `Millions of Americans are already talking about this. Here's why it matters to YOU.`,
      tweet_3: `The opportunity is real. Here are the products making the difference 👇`,
      tweet_4: `My #1 pick right now: [AFFILIATE_LINK_1] — game-changer for this trend!`,
      tweet_5: `Over 50,000 five-star reviews. The numbers don't lie.`,
      tweet_6: `Best value option: [AFFILIATE_LINK_2] — same quality, lower price.`,
      tweet_7: `Full breakdown + all picks 👉 [AFFILIATE_LINK_2] Don't sleep on this! #ad #trending`,
