const tt = content.twitter_thread || {};
const hashtags = (tt.hashtags || []).join(' ');
const tweetTexts = [tt.tweet_1, tt.tweet_2, tt.tweet_3, tt.tweet_4, tt.tweet_5, tt.tweet_6, tt.tweet_7].filter(Boolean);
const firstTweet = (tt.tweet_1 || `🔥 ${item.title} is trending!`) + '\n\n' + hashtags;
const fullThread = tweetTexts.map((t, i) => `${i + 1}/${tweetTexts.length} ${t}`).join('\n\n');

const bp = content.blog_post || {};
let blogHtml = bp.intro ? `<p class="lead">${bp.intro}</p>\n\n` : '';
for (const section of (bp.sections || [])) {
  blogHtml += `<h2>${section.heading}</h2>\n<p>${section.content}</p>\n`;
  for (const prod of (section.affiliate_products || [])) {
    blogHtml += `\n<div class="affiliate-box">\n`;
    blogHtml += `  <h4>🏆 ${prod.name}</h4>\n  <p>${prod.description}</p>\n`;
    if (prod.price_range) blogHtml += `  <p><strong>Price:</strong> ${prod.price_range}</p>\n`;
    blogHtml += `  <a href="${prod.placeholder_link}" rel="nofollow sponsored" class="btn-affiliate">${prod.cta_text || 'Check Price'}</a>\n</div>\n\n`;
  }
}
if (bp.conclusion) blogHtml += `<h2>Final Thoughts</h2>\n<p>${bp.conclusion}</p>\n`;

const fb = content.facebook_post || {};
const facebookMessage = (fb.text || '') + '\n\n' + (fb.hashtags || []).join(' ');
const email = content.email_newsletter || {};
const seo = content.seo_data || {};
