return [{
  json: {
    trend_title: item.title, trend_source: item.source, trend_rank: item.rank,
    trend_score: item.trend_score, affiliate_potential: item.affiliate_potential,
    processed_at: item.processed_at, execution_date: item.execution_date,
    topic_analysis: content.topic_analysis,
    twitter_first_tweet: firstTweet, twitter_full_thread: fullThread, twitter_hashtags: hashtags,
    blog_title: bp.title || `Trending: ${item.title}`, blog_slug: blogSlug,
    blog_meta_description: bp.meta_description || '', blog_html_content: blogHtml,
    blog_tags: (bp.tags || item.keywords || []).join(','),
    blog_category: bp.category || item.category || 'Trends',
    facebook_message: facebookMessage,
    email_subject: email.subject_line_a || `Trending: ${item.title}`,
    email_subject_b: email.subject_line_b || '',
    email_preheader: email.preheader || '', email_greeting: email.greeting || 'Hey there,',
    email_body: email.body || '', email_cta_text: email.cta_button_text || 'Learn More',
    email_ps: email.ps_line || '',
    seo_primary_keyword: seo.primary_keyword || item.title,
    seo_secondary_keywords: (seo.secondary_keywords || []).join(', '),
    seo_long_tail: (seo.long_tail_keywords || []).join(' | ')
  }
}];

