const item = $input.first().json;
const apiKey = process.env.MAILCHIMP_API_KEY || '';
const listId = process.env.MAILCHIMP_LIST_ID || '';
const server = process.env.MAILCHIMP_SERVER || 'us1';

if (!apiKey || !listId) {
  return [{ json: { mailchimp_status: 'skipped', mailchimp_reason: 'Missing credentials', ...item } }];
}

const baseUrl = `https://${server}.api.mailchimp.com/3.0`;
const authHeader = 'Basic ' + Buffer.from(`anystring:${apiKey}`).toString('base64');

const emailHtml = `<!DOCTYPE html><html><head><meta charset=\"UTF-8\"></head><body style=\"font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;color:#333;\"><h1 style=\"color:#e44d26;\">${item.email_subject || item.trend_title}</h1><p style=\"color:#666;\">${item.email_preheader || ''}</p><hr><p><strong>${item.email_greeting || 'Hey there,'}</strong></p><div style=\"line-height:1.6;\">${(item.email_body || '').replace(/\\n/g, '<br>')}</div><div style=\"text-align:center;margin:30px 0;\"><a href=\"[AFFILIATE_LINK_MAIN]\" style=\"background:#e44d26;color:white;padding:14px 28px;text-decoration:none;border-radius:6px;font-weight:bold;\">${item.email_cta_text || 'See Top Picks →'}</a></div><p style=\"font-style:italic;color:#666;font-size:13px;\">${item.email_ps || ''}</p><hr><p style=\"font-size:11px;color:#999;\">You're receiving this because you subscribed. <a href=\"*|UNSUB|*\">Unsubscribe</a></p></body></html>`;

try {
  const createResp = await $helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/campaigns`,
    headers: { 'Authorization': authHeader, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      type: 'regular',
      recipients: { list_id: listId },
      settings: {
        subject_line: item.email_subject || `Trending: ${item.trend_title}`,
        preview_text: item.email_preheader || '',
        title: `[Auto] ${item.trend_title} - ${new Date().toLocaleDateString('en-US')}`,
        from_name: process.env.MAILCHIMP_FROM_NAME || 'Affiliate Insights',
        reply_to: process.env.MAILCHIMP_REPLY_TO || 'hello@yoursite.com'
      }
    })
  });
  const campaign = JSON.parse(createResp);
  const campaignId = campaign.id;
  await $helpers.httpRequest({
    method: 'PUT',
    url: `${baseUrl}/campaigns/${campaignId}/content`,
    headers: { 'Authorization': authHeader, 'Content-Type': 'application/json' },
    body: JSON.stringify({ html: emailHtml, plain_text: item.email_body || '' })
  });
  // Décommenter pour envoi automatique:
  // await $helpers.httpRequest({ method: 'POST', url: `${baseUrl}/campaigns/${campaignId}/actions/send`, headers: { 'Authorization': authHeader } });
  return [{ json: { mailchimp_status: 'created_draft', mailchimp_campaign_id: campaignId, ...item } }];
} catch (e) {
  return [{ json: { mailchimp_status: 'error', mailchimp_error: e.message, ...item } }];
}

